insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('ball-joints-mk7','cxca','ball-joints-mk7','Front ball joints','Steering',null,array['ball joint','ball joints','clunk','034 rco','camber ball joint','lemförder','lemforder']::text[],true,'1 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('tie-rods-mk7','cxca','tie-rods-mk7','Tie rods (inner & outer)','Steering',null,array['tie rod','tie rods','outer tie rod','inner tie rod','vague steering','wander','alignment']::text[],true,'1–2 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
