insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('rear-wheel-bearing-mk7','cxca','rear-wheel-bearing-mk7','Rear wheel bearing','Steering','wheel bearings',array['wheel bearing','rear hub','hum','roar','fag','skf','electric parking brake']::text[],true,'1 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('ball-joints-mk7',$j${"id": "ball-joints-mk7", "title": "Front ball joints", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI (same MQB knuckle and control-arm hardware)", "category": "Steering", "kind": "repair", "heroId": "mk7-balljoint", "variants": {"question": "OE replacement or camber-adding?", "hint": "OE ball joints put the car back to stock. Camber-adding joints (034 RCO) move the lower pivot outboard about 5 mm, adding roughly 1.2° of negative camber and dropping the roll center 10 mm — a real handling upgrade that installs in the same place, in the same time.", "options": [{"id": "oe", "label": "OE replacement", "when": "Worn joint, keep factory geometry"}, {"id": "rco", "label": "034 camber-adding (RCO)", "brand": true, "when": "Add negative camber without buying camber plates"}]}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$60–120 (OE pair) · $300 (034 RCO pair) · + alignment for RCO", "risk": "Car on stands · a stubborn joint may need a puller · alignment recommended", "why": "On a Mk7 the ball joint is a separate three-bolt part, not built into the control arm the way it is on a Mk5. When it wears it clunks on bumps and the front feels loose in corners. Two paths for the same swap: OE puts the car back to stock, or the 034 camber-adding joint uses that same hour to give you the negative camber a lowered Mk7 wants.", "note": "FCP says the whole job is 'a couple of hand tools.' 034 rates their guide 'Mild.' Reality: an hour if the joint pops off cleanly, two if it fights."}, "heroCap": "Front knuckle with the ball joint attached: one M12 nut on top through the knuckle, three M10 nuts underneath into the lower control arm. Nothing else has to come apart.", "lifespan": {"title": "When to expect it", "headline": ["Commonly worn past 80,000–100,000 miles; anecdotal, no factory interval"], "earliest": "Sooner if the boot tears and grease leaves the joint", "detail": "The symptom pattern: hollow clunk from one corner over small bumps, worst at low speed, sometimes a slight looseness in the wheel when you grab it at 6 and 12 and rock it (with the car on stands). A torn boot is the visible sign; the grease is gone within a few thousand miles once the boot is open.", "factors": ["Salt-belt corrosion", "Curbing", "Aftermarket lowering, which loads the joint at an angle it wasn't designed for"], "inspect": ["Wiggle test with both hands, wheel off, car on the stands. Any play here is done.", "Check the boot for tears or leaking grease."], "confidence": {"level": "community", "n": 3, "note": "Vendor articles and forum threads; mileage varies."}}, "should": {"yesIf": ["Clunk from a corner over small bumps that follows the car, not the tires", "Torn boot or missing grease", "Visible play at the joint on the wiggle test", "You're already going to have the wheels off and want a fresh set of joints", "You're lowered and want more negative camber without buying plates"], "codes": [], "notes": ["Both sides. The other joint has the same mileage and is close behind, and a mismatched pair drives poorly.", "The knuckle can stay in the car for this. Nothing about the strut, axle or brakes needs to come apart. That's what makes it a one-hour job.", {"text": "OE ball joints (Lemförder makes the OE part) are the answer if the goal is to fix a clunk. Genuine kit numbers: left 3C0-407-365-A, right 3C0-407-366-A. FCP's kit (3C0407365BKT1) is the two Lemförder joints together.", "only": ["oe"]}, {"text": "The 034 RCO joint (034-401-4013) uses a longer stud so the knuckle sits about 5 mm further outboard at the bottom, which tilts the top of the wheel in. It fits in the same three bolt holes and the same top nut, so the install is the same. An alignment is required after; the extra camber is only useful if it's set at the shop.", "only": ["rco"]}, "Torque disagreements exist for these fasteners and are documented in the guide. Use fresh nuts either way; they're self-locking and single-use."], "confidence": {"level": "high", "n": 4, "note": "FCP Euro's Mk7 ball joint article, 034's install PDF, ECS's control-arm install PDF, and MyGolfMk7's torque-spec table all describe the same job."}}, "parts": [{"tier": "oe", "name": "Front ball joint kit (left + right)", "pn": "Lemförder 3C0-407-365-A / 3C0-407-366-A · FCP kit 3C0407365BKT1", "note": "Lemförder is the OE maker", "price": "$60–120", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "034 Motorsport Dynamic+ RCO ball joint pair", "pn": "034-401-4013", "note": "+1.2° camber, roll center down 10 mm", "price": "$275–320", "links": [{"store": "034 install guide (PDF)", "url": "https://www.034motorsport.com/docs/034-401-4013-Install_Instructions.pdf"}], "only": ["rco"]}, {"tier": "oe", "name": "M10 self-locking nuts (×6, three per side, into the control arm)", "pn": "N 10 332 002", "note": "Single-use; kit-supplied on 034", "price": "$8", "links": []}, {"tier": "oe", "name": "M12 self-locking nut (×2, one per side, top through the knuckle)", "pn": "N 90 226 501", "note": "Single-use", "price": "$4", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Required after 034 RCO; recommended after OE if you removed the whole knuckle", "price": "$100–150", "links": [], "only": ["rco"]}], "aftermarket": [{"name": "034 Motorsport RCO (Roll Center Optimized)", "note": "+1.2° camber and +0.5° caster, drops the roll center 10 mm. Same install, same time. FCP and Grassroots Motorsports both note that it stays quiet on the street unlike camber plates.", "price": "$275–320", "signal": "Only real upgrade", "links": []}, {"name": "Adjustable ball joints", "note": "None currently in production for the MQB. SuperPro looked into it and told a forum member the packaging can't be made to work.", "price": "—", "signal": "Not available"}], "tools": [{"name": "Jack + two stands, 17 mm socket for lugs"}, {"name": "16 mm socket (M10 nuts into the control arm) and 18 mm wrench (M12 top nut)"}, {"name": "7 mm allen bit or T40 Torx", "note": "holds the top stud from spinning while the M12 nut turns"}, {"name": "Ball joint separator (pickle fork or press-type)", "note": "only if the joint refuses to drop out of the knuckle; the press-type doesn't tear boots"}, {"name": "Torque wrench (to 60 Nm minimum), angle gauge or paint pen"}, {"name": "Penetrating oil, wire brush, safety glasses"}], "before": ["Level ground, both front wheels off the ground together so no side is loaded.", "Soak the four nuts on each side with penetrating oil.", "Wiggle test first if you haven't confirmed diagnosis: hands at 12 and 6, rock the wheel in and out. Any clunk or play is the joint.", "The upper nut is torqued with the car on the ground so the joint isn't clamped at a strange angle; the three lower nuts can be torqued in the air."], "steps": [{"n": 1, "title": "Wheels off, take a look", "blocks": [{"t": "text", "b": "Loosen the lugs, raise both fronts, stands under the body, wheels off. The ball joint is right there: pear-shaped body bolted to the underside of the knuckle with three M10 nuts, its stud passing up through the knuckle with an M12 nut on top."}, {"t": "ill", "id": "mk7-balljoint", "cap": "Three nuts into the control arm from below, one nut on the stud from above. No axle, no strut, no brakes to move."}]}, {"n": 2, "title": "Break the top nut loose", "blocks": [{"t": "text", "b": "With the wheel off you can reach the top nut with an 18 mm wrench. Just break it loose; don't remove it yet. If the stud spins with the nut, drop a 7 mm allen or T40 Torx into the top of the stud and counter-hold. If the axle is in the way, you can loosen this nut with the wheel back on and the car on the ground, using the load to keep the stud still."}]}, {"n": 3, "title": "Three nuts off, ball joint drops", "blocks": [{"t": "text", "b": "16 mm on the three M10 nuts that secure the ball joint to the underside of the lower control arm. All three off, then the top nut off. Push down on the control arm and the joint should drop out of the knuckle."}, {"t": "warn", "b": "If it won't drop, a press-type separator (not a pickle fork) between the joint body and the knuckle pops it loose without tearing the new boot. These things pop — hand out of the way."}]}, {"n": 4, "title": "New joint in", "blocks": [{"t": "text", "b": "Stud through the knuckle from below, joint body up against the control arm. Start the M12 top nut a few threads by hand. Line up the three M10 studs with the arm and start those nuts by hand too."}, {"t": "text", "b": "034 RCO only: install the supplied M12 washer under the top nut before starting it. Skip the washer and the geometry is wrong.", "only": ["rco"]}]}, {"n": 5, "title": "Torque the three lower nuts", "blocks": [{"t": "text", "b": "Snug them down evenly across the three, then torque. This is where the sources disagree."}, {"t": "torque", "label": "Ball joint to control arm, three M10 nuts", "nm": 45, "alt": [40, 100], "note": "+45° turn", "c": {"level": "varies", "n": 3, "note": "034 (RCO kit): 45 Nm + 45°. ECS (Mk7 control-arm install): 40 Nm + 45°. 034's control-arm PDF: 100 Nm flat, for the factory nuts against a new arm. The 45 Nm + 45° number is the RCO kit's own hardware and matches ECS within 5 Nm; use that when replacing the joint alone."}}]}, {"n": 6, "title": "Wheels on, car down, torque the top nut", "blocks": [{"t": "text", "b": "Wheels back on (120 Nm), lower the car. Now the top nut can be torqued without the stud trying to spin — the load holds it."}, {"t": "torque", "label": "Ball joint top nut (M12, through knuckle)", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm: 034 RCO guide and MyGolfMk7 (steering ball joint to knuckle carrier)."}}]}, {"n": 7, "title": "Alignment", "blocks": [{"t": "text", "b": "An OE swap of a worn joint usually leaves toe close enough to drive to the alignment shop the next morning. A 034 RCO swap changes camber and caster on purpose; that's the whole reason to do it, and it needs an alignment before the car sees a corner harder than the parking lot exit.", "only": ["rco"]}, {"t": "text", "b": "OE swap: alignment recommended, not required. If the car doesn't pull and the steering wheel is straight, you're probably close.", "only": ["oe"]}]}], "alsoReplace": [{"name": "Front control-arm bushings", "why": "They live in the same subframe pocket and wear on the same clock. Once you're checking one, check both. Full bushing job in its own guide."}, {"name": "Front sway-bar end links", "why": "Only if they're already tired; they don't have to come off for this job, but the diagnosis for clunk overlaps."}, {"name": "Wheel alignment", "why": "Any suspension separation is a small excuse for one; a 034 RCO install requires it."}], "check": {"tab": "Diagnosis", "title": "Is it really the ball joint?", "illId": "mk7-balljoint", "illCap": "Wiggle test at 12 and 6 vs at 3 and 9 separates ball joint from tie rod.", "rows": [{"see": "Clunk over small bumps at low speed, one corner", "means": "Classic ball joint. Wiggle test confirms.", "do": "Both joints on that axle, OE."}, {"see": "Play at 12 and 6 (up/down), no play at 3 and 9 (in/out)", "means": "Ball joint (vertical axis).", "do": "Replace both."}, {"see": "Play at 3 and 9, no play at 12 and 6", "means": "Tie rod, not ball joint.", "do": "See the tie rod guide."}, {"see": "Boot torn, no play yet", "means": "Grease is on its way out; failure is coming.", "do": "Replace now, not later."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis; matches FCP and forum accounts."}}, "aftercare": ["Alignment (mandatory for RCO, recommended for OE).", "Re-check the top nut after 50 miles; that one gets loaded hard.", "New clunk after the job: three lower nuts torqued out of sequence, or a top nut that didn't reach spec because the stud was spinning."], "disagreements": [{"topic": "Lower nut torque", "pos": "034 RCO: 45 Nm + 45°. ECS Mk7 arms: 40 Nm + 45°. 034 control-arm PDF: 100 Nm flat.", "call": "45 Nm + 45° for the joint alone; the 100 Nm number is for a full arm swap against fresh nuts, not the ball-joint-only case."}, {"topic": "OE brand", "pos": "FCP sells Lemförder as OE. Some vendors sell TRW or Delphi.", "call": "Lemförder. It's the maker of the original part."}, {"topic": "Do the arms have to come out?", "pos": "Some older DIYs pull the arm.", "call": "No. Three nuts under the arm, one on top of the knuckle. The arm stays."}], "sources": ["FCP Euro Mk7 ball joint kit article (Evan Madore, 2019)", "034 Motorsport RCO camber-adding ball joint install guide (034-401-4013)", "034 Motorsport Dynamic+ RCO control-arm listing (adjustment ranges)", "ECS Tuning Mk7 performance control-arm install (control-arm and ball joint torques)", "MyGolfMk7 torque spec table (steering: ball joint to knuckle 60 Nm, ball joint to control arm 40 Nm + 45°)", "GolfMK7 and VWVortex ball-joint diagnosis threads"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('tie-rods-mk7',$j${"id": "tie-rods-mk7", "title": "Tie rods (inner & outer)", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI (same steering rack family)", "category": "Steering", "kind": "repair", "heroId": "mk7-tierod", "variants": {"question": "Outer only, or inner & outer?", "hint": "The outer tie rod end is the exposed ball joint at the knuckle. The inner tie rod is hidden under the rack boot, threading into the end of the steering rack. Play at 3 and 9 with a torn outer boot is usually the outer; play at 3 and 9 with an intact outer boot points to the inner.", "options": [{"id": "outer", "label": "Outer only", "when": "Ball joint at the knuckle has play; boot torn or missing"}, {"id": "both", "label": "Inner and outer", "when": "Play remains after checking the outer, or both boots are gone"}]}, "glance": {"timeFirst": "1 hr (outer) · 2 hr (both)", "timeRepeat": "30 min (outer) · 90 min (both)", "difficulty": 2, "cost": "$40–80 pair (outer) · $80–160 pair (inner+outer) · + alignment", "risk": "Alignment required · inner needs a special socket · a boot clamp is fiddly", "why": "Tie rods are the two rods running from the steering rack out to the wheels. They're what actually turn the wheels when you turn the wheel. When a joint wears the steering goes vague, the car wanders in its lane, and the inside or outside edge of a front tire scrubs down. Uncommon before 100k on a Mk7; when it happens it's usually the outer, which is exposed.", "note": "Outer-only is a straightforward job. Inner requires an inner tie rod tool (essentially a long crow's foot that grips the flats on the inner) and getting the rack boot off, which is the fiddliest part of the whole job."}, "heroCap": "Rack → inner tie rod (under the boot) → outer tie rod end (at the knuckle). The jam nut between them sets total length, which is the toe alignment.", "lifespan": {"title": "When to expect it", "headline": ["Uncommon before 100,000 miles; sooner if the outer boot has torn"], "earliest": "Immediately after a curb strike or hard pothole hit — inspect the same day", "detail": "Vague steering, drift in the lane, feathered wear on the inside or outside edge of one front tire. A clunk when going over expansion joints or rocking the wheel side-to-side on stands. The outer's boot is exposed to the road; when it splits, water finds the ball socket and wear accelerates.", "factors": ["Curbs and hard potholes", "Torn boot", "Aggressive lowering that puts the tie rod at a steep angle", "Salt and grit"], "inspect": ["Wiggle test at 3 and 9 (side to side) is the tie rod test; play here, not at 12 and 6, points to a tie rod", "Squeeze the outer boot for any grease leaking out"], "confidence": {"level": "community", "n": 3, "note": "Symptom patterns and diagnosis are standard across VW/Audi tie rod DIYs; Mk7-specific mileage is anecdotal."}}, "should": {"yesIf": ["Vague steering that has gotten worse", "Wandering at highway speed", "Feathered wear on one front tire's edge", "Clunk from the front when going straight over rough pavement", "Torn outer boot found during a wheel-off inspection", "You just hit a curb hard and want to be sure"], "codes": [], "notes": ["Both sides on the same axle. Same mileage, same wear.", {"text": "Outer only is the common case. Mark the position of the outer on the inner's threads with a paint pen before you unscrew it — if you back the new one on the same number of turns, your toe will be close enough to drive gently to the shop for alignment.", "only": ["outer"]}, {"text": "Inner tie rod means the steering rack boot has to come off (two spring clamps, then slide). The inner threads into the end of the rack and needs a special socket-style tool ('inner tie rod tool' or 'crow's foot for tie rod') to reach it past the rack housing. A 32 mm open-end on the flats works but is slow.", "only": ["both"]}, "Alignment is required after any tie rod change, no matter how careful you were with reference marks. The DIY marks get you home; the shop sets the actual toe."], "confidence": {"level": "high", "n": 3, "note": "Method matches VW/Audi tie rod DIYs across generations; Mk7-specific hardware from ECS and vendor listings."}}, "parts": [{"tier": "oe", "name": "Outer tie rod end, each side", "pn": "Lemförder 35280 01", "note": "Same part left and right", "price": "$20–35 each", "links": []}, {"tier": "oe", "name": "Inner tie rod, each side", "pn": "Lemförder", "note": "Same part left and right", "price": "$25–45 each", "links": [], "only": ["both"]}, {"tier": "oe", "name": "Steering rack boot + clamps", "pn": "factory", "note": "Only if the boot is torn; often reusable", "price": "$15–25", "links": [], "only": ["both"]}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Required, both cases", "price": "$100–150", "links": []}], "aftermarket": [{"name": "Meyle HD", "note": "Reinforced ends, popular Euro-car upgrade. Known to run tighter than OE, which some like and some don't; forum threads on other VWs report early creaks from over-tight joints, so torque carefully.", "price": "$60–100 a pair", "signal": "Firmer feel", "links": []}, {"name": "TRW / Delphi", "note": "OE-adjacent brands, sold as budget kits. Acceptable for a daily; not the pick if you can find Lemförder.", "price": "$40–70 a pair", "signal": "Budget", "links": []}], "tools": [{"name": "Jack + two stands, 17 mm lug socket"}, {"name": "Two 22 mm wrenches (jam nut and outer flats), or an adjustable wrench and 22 mm", "note": "outer tie rod flats"}, {"name": "Ball joint separator or tie-rod puller for the outer at the knuckle"}, {"name": "Inner tie rod tool (or 32 mm open-end wrench), boot clamp pliers, small screwdriver", "only": ["both"]}, {"name": "Torque wrench, paint pen, tape measure"}], "before": ["Level ground. One side at a time is fine; you can leave the other steering-side loaded so nothing swings around.", "Steering wheel straight before you start. This gets the rack centered, which matters if the boot comes off.", {"text": "Paint-pen mark on the outer's exposed threads at the jam nut, and count turns as it comes off. This is how the toe stays close.", "only": ["outer"]}, "Inspect the rack boot before ordering. If it's torn, add a new boot to the parts list.", "Book the alignment. Don't drive on a fresh tie rod farther than the shop."], "steps": [{"n": 1, "title": "Wheel off, mark the outer", "blocks": [{"t": "text", "b": "Loosen the lugs, jack, stand, wheel off. Turn the wheel to full lock away from the tie rod you're working on so you have room."}, {"t": "text", "b": "Paint-pen mark across the outer tie rod's exposed threads and the jam nut. This is your zero point.", "only": ["outer", "both"]}]}, {"n": 2, "title": "Outer off the knuckle", "blocks": [{"t": "text", "b": "22 mm on the outer's nut where its stud passes through the steering arm on the knuckle. Nut off. Use a ball-joint separator (press-type is kindest to the new boot) to pop the stud out of the arm."}, {"t": "ill", "id": "mk7-tierod", "cap": "Two joints per side: outer at the knuckle, inner under the boot. Jam nut sets total length."}]}, {"n": 3, "title": "Outer off the inner", "blocks": [{"t": "text", "b": "Loosen the 22 mm jam nut (a couple of turns is enough), then unscrew the outer end counter-clockwise off the inner. Count the turns."}, {"t": "text", "b": "Thread the new outer on the same number of turns. Your paint mark should line back up. Don't tighten the jam nut yet.", "only": ["outer"]}]}, {"n": 4, "title": "Rack boot and inner", "only": ["both"], "blocks": [{"t": "text", "b": "Two spring clamps hold the accordion boot: the inner clamp on the rack body, the outer clamp on the inner tie rod. Pinch and slide each clamp off with the boot clamp pliers or a pair of side cutters (carefully). Slide the boot toward the outer end and off; check it for tears while it's off."}]}, {"n": 5, "title": "Inner off the rack", "only": ["both"], "blocks": [{"t": "text", "b": "Steer to the opposite lock so this side's inner extends. The inner threads into the end of the rack. Put the inner tie rod tool over it, engage the flats, and unscrew it counter-clockwise. It'll take a good pull for the first quarter turn."}, {"t": "note", "b": "32 mm open-end on the flats works if you don't have the tool. It's slower and you may hit the subframe with the wrench; a longer wrench with a bend helps."}]}, {"n": 6, "title": "New inner on", "only": ["both"], "blocks": [{"t": "text", "b": "Thread the new inner into the rack by hand until it stops, then torque. A dab of blue thread-locker on the threads is a good idea; it's not required, but it costs nothing and makes it certain."}, {"t": "torque", "label": "Inner tie rod to rack", "nm": 80, "alt": [75], "c": {"level": "varies", "n": 2, "note": "MQB manuals for this rack family give 80 Nm. Some older VW/Audi generations use 75 Nm on similar racks. Not confirmed on a first-party Mk7 source this pass — treat as best-known value."}}]}, {"n": 7, "title": "Boot back on", "only": ["both"], "blocks": [{"t": "text", "b": "Slide the boot down over the inner and onto the rack. New clamps if you're using them; the old ones can be reused if they aren't sprung. Inner clamp on the rack body groove, outer clamp on the inner tie rod's small groove. The boot should sit flat, not twisted."}]}, {"n": 8, "title": "Outer back on the inner", "only": ["both"], "blocks": [{"t": "text", "b": "Jam nut onto the inner first, then thread the new outer end on. Rough centering: measure from the rack center to the outer's ball, or measure your existing 'good' side and match. This is a starting point only; the alignment shop will set the final toe."}]}, {"n": 9, "title": "Outer stud into the knuckle, torque", "blocks": [{"t": "text", "b": "Push the outer's stud up through the steering arm on the knuckle. New nut (self-locking; the old one is one-time). If the stud spins while you tighten, hold it with a 6 mm allen or T30 in the top of the stud."}, {"t": "torque", "label": "Outer tie rod nut at knuckle", "nm": 45, "c": {"level": "medium", "n": 2, "note": "Cross-generation VW/Audi service data for this joint gives 45 Nm. Not on MyGolfMk7's table this pass; treat as best-known."}}]}, {"n": 10, "title": "Jam nut, then alignment", "blocks": [{"t": "text", "b": "Snug the jam nut against the outer end. Rough toe with a tape measure between the front edges of the tires vs the rear edges is enough to drive to the shop; anything more is guessing."}, {"t": "torque", "label": "Jam nut", "nm": 50, "c": {"level": "medium", "n": 2, "note": "50 Nm is the typical VW/Audi jam-nut value; ECS's Mk4/Mk5 tie-rod guides call for the same."}}, {"t": "text", "b": "Wheel on (120 Nm), other side, then alignment. Do not drive on the highway before the shop resets toe."}]}], "alsoReplace": [{"name": "Rack boot(s)", "why": "Off already; check for tears. A torn boot is why the inner failed in the first place.", "only": ["both"]}, {"name": "Ball joints", "why": "Same age, same corner. If one's gone, look at the other — see the Ball joints guide."}], "check": {"tab": "Diagnosis", "title": "Which tie rod is bad?", "illId": "mk7-tierod", "illCap": "Play at 3 and 9 is a tie rod. Squeeze the outer boot to feel if it's the outer specifically.", "rows": [{"see": "Vague steering, drift, feathered tire wear", "means": "A tie rod somewhere. Confirm with wiggle test.", "do": "Wheels off, wiggle at 3 and 9."}, {"see": "Play at 3 and 9 with outer boot torn", "means": "Outer.", "do": "Outer only, both sides."}, {"see": "Play at 3 and 9 with outer boot intact", "means": "Inner or steering rack.", "do": "Squeeze the rack boot — grease means the inner. Both sides."}, {"see": "Clunk on rough pavement going straight", "means": "Could be tie rod, could be sway link or strut mount.", "do": "Wiggle test first; if that's clean, look upstream."}, {"see": "Recently curbed", "means": "Anything from bent tie rod to bent knuckle.", "do": "Inspect visually; if in doubt, alignment shop first."}], "c": {"level": "high", "n": 3, "note": "Wiggle-test axis matches every VW/Audi tie-rod diagnosis."}}, "aftercare": ["Alignment before the highway.", "Re-check jam nut torque and outer boot seating at 50 miles.", "New clunk after: jam nut not tight, or the outer isn't fully seated on the inner threads (it should thread on by hand until the mark)."], "disagreements": [{"topic": "Inner tie rod torque", "pos": "MQB manual data: 80 Nm. Cross-generation VW/Audi: 75 Nm.", "call": "80 Nm, flagged. Very close either way."}, {"topic": "Outer nut torque", "pos": "Not on the MyGolfMk7 Mk7 table this pass; cross-VW data: 45 Nm.", "call": "45 Nm. Confirm on your car if you can."}, {"topic": "Tool for the inner", "pos": "Inner tie rod tool (crow's foot style) vs 32 mm open-end wrench.", "call": "The tool. Rentable at most parts stores."}], "sources": ["Pelican Parts Mk5 VW GTI tie rod DIY (procedure is the same on the MQB)", "MyGolfMk7 torque spec table (no tie rod entry as of this pass — flagged in disagreements)", "ECS Tuning inner/outer tie rod product listings and installation notes", "VWVortex Mk7 tie-rod threads (symptoms, tool choice, alignment necessity)", "SLRSpeed 'Inner Tie Rod Noise' article (diagnosis)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('front-wheel-bearing-mk7',$j${"id": "front-wheel-bearing-mk7", "title": "Front wheel bearing", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI · same bolt-in Gen 3 hub across the MQB", "category": "Steering", "kind": "repair", "heroId": "mk7-hub-front", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 3, "cost": "$120–200 (unit) + $10 (axle bolt)", "risk": "Axle bolt torque is high (200 Nm + 180°) · single-use axle bolt is mandatory · brake caliper hangs from the hose if you skip a wire tie", "why": "On a Mk7 the front hub is a bolt-in Gen 3 unit — bearing and hub are one piece, four bolts to the knuckle, no press. That's the good news. The bad news is the axle bolt in the middle of the hub, which is on tight enough that first-timers usually snap or bend cheap tools trying to break it. This is a two-hour job with the right breaker bar, and a wrestling match without one.", "note": "The classic diagnostic story: a hum that gets louder with speed, changes when the car turns. If the hum grows in a right-hand turn, the left bearing is loaded and probably bad, and vice versa."}, "heroCap": "Bolt-in Gen 3 hub: four M12 bolts (18 mm 12-point) to the back of the knuckle, one big axle bolt through the middle. The wheel-speed sensor stays put; the hub carries the ABS tone ring inside.", "lifespan": {"title": "When to expect it", "headline": ["Not a maintenance item; failure is anecdotal from 60,000 miles onward, often after a pothole or curb"], "earliest": "Sooner in the salt belt or after a hard curb hit", "detail": "A healthy bearing is silent. When one starts to go it hums, then roars, then grinds. The tell is the sound changing when you turn: heavier load, more noise. A bearing on the way out can also trigger the ABS light because the tone ring wobbles.", "factors": ["Curb strikes", "Deep potholes", "Salt-belt corrosion", "Water intrusion after wheel-off work"], "inspect": ["Wobble test with the wheel off the ground: hands at 12 and 6, any looseness is bad", "Spin the wheel by hand with the brake off — grit or grinding you can feel through the wheel is a bad bearing"], "confidence": {"level": "community", "n": 3, "note": "Diagnostic pattern is standard across VW/Audi bearings; Mk7 mileage is anecdotal."}}, "should": {"yesIf": ["Hum that grows with speed and changes when turning", "Grinding or growling from a specific corner", "ABS light with no other obvious cause", "Play at 12 and 6 when you wiggle the wheel on stands"], "codes": ["ABS wheel-speed sensor faults if the tone ring is damaged"], "notes": ["The axle bolt is single-use. VW is emphatic about this and every DIY that skips it eventually reports a bolt backing out and destroying the new bearing. Two versions exist: hex-head (200 Nm + 180°) and 12-point 'ribbed' (70 Nm + 90°). The MQB Mk7 uses the hex-head; if yours is different, follow the printing on the box the bearing came in.", "Never use an impact wrench on the axle bolt for final torque. Impact is fine for the initial removal; final torque is a torque wrench with an angle gauge, on the ground.", "One side, then the other. Both bearings live under the same conditions; if one's audibly bad, the other is often close."], "confidence": {"level": "high", "n": 4, "note": "Procedure matches Mk5 Pelican write-up, Mk6 QA references, and MQB hub is the same bolt-in Gen 3 design."}}, "parts": [{"tier": "oe", "name": "Front hub assembly (Gen 3, bolt-in)", "pn": "5Q0 407 621 (or FAG / SKF equivalent)", "note": "OE brand FAG. Bearing and hub are one part.", "price": "$120–200", "links": []}, {"tier": "oe", "name": "Axle bolt, hex head (M14)", "pn": "N 911 715 01", "note": "Single-use, torque-to-yield", "price": "$8–12", "links": []}, {"tier": "oe", "name": "Rotor set screw (T30)", "pn": "factory", "note": "$3, but always seized; grab a spare", "price": "$3", "links": []}], "aftermarket": [{"name": "FAG / SKF branded units", "note": "FAG is the OE supplier. SKF is the other big name and known-good. Pay for one of these two.", "price": "$120–200", "signal": "OE quality"}, {"name": "Timken", "note": "Reputable third choice; fits the same and lasts.", "price": "$110–180", "signal": "Also fine"}, {"name": "Detroit Axle / no-name eBay hubs", "note": "Half the price, half the life. Owner reports of noisy new bearings and ABS sensor issues within a few thousand miles. Skip.", "price": "$40–70", "signal": "Don't"}], "tools": [{"name": "Jack + two stands, 17 mm lug socket, wire or bungee to hang the caliper"}, {"name": "Big breaker bar (at least 24 in), a length of pipe as a cheater", "note": "the axle bolt lives here"}, {"name": "18 mm 12-point (triple-square) socket, 3/8 drive is fine for the four hub bolts", "note": "cheap sets round out; buy one decent bit"}, {"name": "21 mm socket for the caliper carrier · T30 Torx for the rotor set screw"}, {"name": "Torque wrench to at least 200 Nm and an angle gauge (or a paint pen and patience)"}, {"name": "Impact wrench (optional but very welcome for initial removal)"}, {"name": "Penetrating oil, wire brush, small hammer"}], "before": ["Level ground. Wheels on the ground until the axle bolt is loose.", "Loosen the lugs, then loosen the axle bolt (30 mm hex) with the car on the ground. This is where a breaker bar and cheater pipe earn their keep. Do not fully remove yet.", "Now raise the car, stand under the body, wheel off.", "Book the alignment afterwards only if you had to move the knuckle or a ball joint separator was involved; a straight hub swap doesn't move any alignment surface."], "steps": [{"n": 1, "title": "Break the axle bolt loose on the ground", "caution": true, "blocks": [{"t": "text", "b": "Center cap off the wheel. 30 mm socket, breaker bar, cheater pipe if needed. Break the axle bolt loose while the car is on its wheels — the tire's grip on the ground stops the whole car from turning. Just loosen; do not remove."}, {"t": "warn", "b": "Never spin an axle bolt with an impact while the wheel is off the ground and unloaded. The bearing takes the whole hit."}]}, {"n": 2, "title": "Raise the car, wheel off, brake apart", "blocks": [{"t": "text", "b": "Lug bolts, jack, stand, wheel off. Two 21 mm caliper carrier bolts on the back of the caliper bracket — off, and hang the whole caliper (still assembled) from a bungee or wire to the spring. Do not let it dangle from the brake hose."}, {"t": "text", "b": "T30 screw between the wheel-bolt holes on the rotor — off. Rotor comes off. A tap with a soft mallet on the back if it's stuck to the hub."}]}, {"n": 3, "title": "Axle bolt out, axle out of the hub", "blocks": [{"t": "text", "b": "Now the axle bolt spins out easily. Old bolt in the recycling bin (it is done). Pull the axle out of the hub splines toward the front of the car; a shove with the palm is usually enough. If it's stuck, a screw-in axle puller helps, but most Mk7 axles come out by hand."}, {"t": "ill", "id": "mk7-hub-front", "cap": "Four bolts through the back of the knuckle. The wheel-speed sensor stays in the knuckle; the ABS tone ring is inside the hub."}]}, {"n": 4, "title": "Four hub bolts", "blocks": [{"t": "text", "b": "Come around to the back of the knuckle. Four M12 12-point bolts hold the hub in. 18 mm triple-square, 3/8 drive with a shortish extension. Some may need help — angle a longer extension between the axle and the tie rod if you can't get straight on."}, {"t": "note", "b": "The steel bolts can rust into the knuckle in cold-country cars. Penetrating oil in advance, tap each bolt head with a small hammer before turning to break the corrosion, and pull steadily rather than jerking."}]}, {"n": 5, "title": "Old hub off, new hub in", "blocks": [{"t": "text", "b": "With four bolts out, the hub pulls off the front of the knuckle. If it's seized, a slide hammer with a hub adapter is the clean way; a couple of taps with a dead-blow on alternating sides also works. Do not hit the wheel-speed sensor."}, {"t": "text", "b": "Wire-brush the knuckle's mating face. A speck of grit or rust lifts the new hub and gives you a wobble. Fit the new hub, four new-condition threads or new bolts. Torque the four hub bolts in a cross pattern."}, {"t": "torque", "label": "Hub-to-knuckle bolts (M12 ×4)", "nm": 70, "note": "+90° turn", "c": {"level": "high", "n": 3, "note": "70 Nm + 90°: Mk5/Mk6 tables and the MyGolfMk6 QA thread; the MQB uses the same M12 pattern."}}]}, {"n": 6, "title": "Axle back through, new axle bolt started", "blocks": [{"t": "text", "b": "Grease the splines lightly (a dab; a smear is enough). Push the axle into the hub, engage splines. Start the new axle bolt by hand a few threads."}, {"t": "warn", "b": "Do not run the axle bolt down with an impact. Snug it by hand for now; the full torque is on the ground."}]}, {"n": 7, "title": "Rotor and caliper back on", "blocks": [{"t": "text", "b": "Rotor onto the hub, T30 set screw in. Caliper bracket back over the rotor, two 21 mm bolts."}, {"t": "torque", "label": "Rotor set screw", "nm": 8, "c": {"level": "high", "n": 1, "note": "8 Nm: MyGolfMk7 (front rotor bolt)."}}, {"t": "torque", "label": "Caliper carrier to knuckle (×2)", "nm": 200, "c": {"level": "high", "n": 2, "note": "200 Nm: MyGolfMk7 (front caliper to bearing housing)."}}]}, {"n": 8, "title": "Wheel on, car down, axle bolt to torque", "caution": true, "blocks": [{"t": "text", "b": "Wheel back on to hand-tight. Lower the car. Lug bolts to 120 Nm. Now the axle bolt: 200 Nm first, then +180°. A paint pen mark on the bolt head and on the hub next to it makes the half-turn obvious."}, {"t": "torque", "label": "Axle bolt, hex head (NEW)", "nm": 200, "note": "+180° turn", "c": {"level": "high", "n": 3, "note": "200 Nm + 180° for the hex-head axle bolt: MyGolfMk7 (main axle bolt), Mk5 Bentley reference, Mk6 QA."}, "only": ["hex"]}, {"t": "torque", "label": "Axle bolt (single value shown below covers the common hex-head case)", "nm": 200, "note": "+180° turn", "c": {"level": "high", "n": 3, "note": "200 Nm + 180° for the hex-head bolt. The alternative 'ribbed 12-point' variant used on some other cars in this family is 70 Nm + 90°; the packaging on the OE bolt will state which. Match the bolt."}}, {"t": "warn", "b": "Never use an impact wrench for this. The bolt is torque-to-yield; the angle after 200 Nm is what stretches it into its final tension, and an impact can't do that predictably."}]}, {"n": 9, "title": "First drive", "blocks": [{"t": "text", "b": "Slow first, then normal. The bearing should be silent. A new hum immediately means the hub isn't seated flat against the knuckle (grit on the mating face) or a hub bolt didn't reach torque. Any ABS light: the wheel-speed sensor is dirty, or its plug wasn't fully clicked in."}]}], "alsoReplace": [{"name": "Wheel-speed sensor", "why": "It's right there and $30. If the old one is corroded or its plug is brittle, replace now rather than chasing a fault code later."}, {"name": "Brake pads and rotors", "why": "Only if they're due. Never do a bearing solely to change pads; do the pads because they're worn."}], "check": {"tab": "Diagnosis", "title": "Is it a bearing?", "illId": "mk7-hub-front", "illCap": "Bearing hum tracks with speed and shifts with turns. Tire noise doesn't shift with turns.", "rows": [{"see": "Hum that gets louder with speed, worse turning one way", "means": "Bearing on the side that gets more load in the noisy turn.", "do": "Right turn noisier = left bearing bad."}, {"see": "Roar that's the same at all speeds and doesn't change turning", "means": "Tires (cupped, worn, all-terrain).", "do": "Look at the tires. Not a bearing."}, {"see": "Grinding you can feel through the pedal", "means": "Bearing well past its date, or a brake dragging.", "do": "Bearing job; check the pads while you're in there."}, {"see": "ABS light with wheel-speed fault", "means": "Damaged tone ring on the hub, or a dirty sensor.", "do": "Clean the sensor first; if it comes back, replace the hub."}], "c": {"level": "high", "n": 3, "note": "Speed/turn diagnosis is standard across all vendors."}}, "aftercare": ["Drive to your alignment shop only if you disturbed a ball joint or tie rod separately; the bearing swap alone doesn't need alignment.", "Re-torque the four hub bolts at 100 miles.", "New noise, same corner: hub not seated flat, or a cheap hub. Pull it, wire-brush the mating face."], "disagreements": [{"topic": "Axle bolt torque, hex vs 12-point", "pos": "Hex head: 200 Nm + 180°. 12-point ribbed: 70 Nm + 90°.", "call": "Match the bolt. MQB Mk7 is the hex head; if the box says otherwise, follow the box."}, {"topic": "Impact wrench for the axle bolt", "pos": "Common shop practice.", "call": "For removal only. Final torque is a wrench with an angle gauge, on the ground. This is a stretch bolt."}, {"topic": "Reuse vs replace axle bolt", "pos": "Some DIYs reuse it.", "call": "Replace. Stretch bolts don't stretch twice."}], "sources": ["MyGolfMk7 torque spec table (axle 200 Nm + 180°, hub 70 Nm + 90°, caliper 200 Nm, rotor set screw 8 Nm)", "Pelican Parts Mk5 GTI front wheel bearing DIY (same bolt-in Gen 3 layout)", "JustAnswer Mk6 wheel bearing QA (hex vs ribbed bolt distinction)", "MyTiguan wheel bearing torque thread", "T1A Auto front wheel bearing diagnostic pattern", "GolfMK7 wheel-bearing threads"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('rear-wheel-bearing-mk7',$j${"id": "rear-wheel-bearing-mk7", "title": "Rear wheel bearing", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI (multilink) · Golf R (uses a different bolt-in unit that also comes with a new axle bolt in the kit)", "category": "Steering", "kind": "repair", "heroId": "mk7-hub-rear", "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$70–150 (unit)", "risk": "Parking-brake needs to retract via VCDS/OBDeleven · a stubborn hub bolt · single-use hub bolts", "why": "Same layout as the front — bolt-in Gen 3 unit — but easier: no axle bolt to fight, no half-shaft to slide out. On a FWD GTI it's three (M12) bolts holding the hub to the knuckle, plus caliper and rotor. Golf R kits ship with an extra axle bolt because the R has a driven rear.", "note": "The FWD hub bolts are 70 Nm + 90°; the R's are the same. The parking brake is electric; retract it before you take the caliper off, or you'll fight the pistons."}, "heroCap": "Rear hub, FWD car: three bolts through the back of the knuckle. Caliper and rotor off; no axle to slide out.", "lifespan": {"title": "When to expect it", "headline": ["Uncommon before 80,000 miles; anecdotal, no factory interval"], "earliest": "After a hard curb strike", "detail": "Same symptoms as the front — hum that grows with speed, changes with turns — but coming from the back of the car. Fewer bearings back here fail; the front pair takes the load and the abuse.", "factors": ["Curbs and potholes", "Salt", "Water intrusion"], "inspect": ["Wobble test with the rear in the air, wheel spinning by hand: any looseness or grit is the bearing", "Compare left vs right sound with the car up on stands, wheels turning by hand"], "confidence": {"level": "community", "n": 3, "note": "Same diagnostic pattern as any wheel bearing."}}, "should": {"yesIf": ["Hum that grows with speed and shifts when turning, and it's coming from the back", "Play or roughness on the wobble test", "ABS light with a rear wheel-speed fault"], "codes": ["Rear wheel-speed sensor faults if the tone ring is damaged"], "notes": ["Retract the electric parking brake before removing the caliper. VCDS: 53-Parking Brake > Basic Settings > 'Release brake pads for maintenance.' OBDeleven has an equivalent 'Service Position.' Skip this and the caliper pistons fight you and can be damaged.", "Both sides live the same life. If one is loud, the other is close behind on the same wheel-off visit.", "The three hub bolts are 12-point M12s, same tool as the front. They're often the tightest fasteners in the job because they take corrosion. Penetrating oil the night before."], "confidence": {"level": "high", "n": 3, "note": "VWVortex Mk7 R rear bearing DIY has the fastener list and torques; FCP Mk5 rear bearing article covers the diagnostic approach."}}, "parts": [{"tier": "oe", "name": "Rear hub assembly (Gen 3, bolt-in)", "pn": "FAG 8V0-598-611 (GTI FWD) · 8V0-598-625-B (Golf R kit with axle bolt)", "note": "OE brand FAG", "price": "$70–150", "links": []}, {"tier": "oe", "name": "Hub bolts (×3 per side)", "pn": "single-use, M12", "note": "Usually included with the FAG kit", "price": "$8", "links": []}, {"tier": "oe", "name": "Caliper carrier bolts (×2 per side)", "pn": "N 911 689 01", "note": "VW calls these single-use; the FAG kit does not include them", "price": "$6", "links": []}, {"tier": "oe", "name": "Rotor set screw", "pn": "T30", "note": "Cheap; get a spare", "price": "$3", "links": []}], "aftermarket": [{"name": "FAG / SKF branded units", "note": "Same story as the front: OE quality is worth it here.", "price": "$70–150", "signal": "OE quality"}, {"name": "Timken", "note": "Fine third choice.", "price": "$60–130", "signal": "Also fine"}, {"name": "Detroit Axle / no-name", "note": "Skip. Rear bearings are cheap enough that saving $30 isn't worth the noise.", "price": "$25–50", "signal": "Don't"}], "tools": [{"name": "Jack + two stands, 17 mm lug socket, wire or bungee to hang the caliper"}, {"name": "18 mm 12-point (triple-square) for the three hub bolts", "note": "1/2 drive if you have it; the bolts are tight"}, {"name": "14 mm triple-square for the caliper carrier bolts", "note": "MyGolfMk7 lists M14 here"}, {"name": "T30 Torx for the rotor set screw"}, {"name": "Brake caliper piston retraction tool (rental at any parts store) — required for the electric parking brake", "note": "or use the VCDS/OBDeleven procedure below to retract the pistons before caliper removal"}, {"name": "VCDS or OBDeleven for the parking-brake service mode", "note": "skip at your peril"}, {"name": "Torque wrench, penetrating oil, wire brush"}], "before": ["Level ground, both rears up so the car isn't loading one side.", "VCDS or OBDeleven: retract the parking brake into service mode. Do this first, before anything mechanical.", "Soak the three M12 hub bolts on the back of the knuckle with penetrating oil while the wheels come off.", "Book alignment only if you plan to disturb a control arm; a bearing swap alone doesn't move alignment."], "steps": [{"n": 1, "title": "Parking brake into service mode", "caution": true, "blocks": [{"t": "text", "b": "Ignition on, engine off. VCDS: address 53 (Parking Brake) > Basic Settings > 'Release brake pads for maintenance.' OBDeleven: Control Units > Parking Brake > Service Position. Both go through the same routine and the caliper pistons retract into the calipers."}, {"t": "warn", "b": "If you skip this and try to compress the pistons with a wind-back tool, on the Mk7 electric brake you'll damage the actuator. Do the service routine first every time."}]}, {"n": 2, "title": "Raise, wheels off", "blocks": [{"t": "text", "b": "Lugs loose on the ground, raise both sides of the rear, stands, wheels off."}]}, {"n": 3, "title": "Caliper and rotor off", "blocks": [{"t": "text", "b": "Two 14 mm triple-square bolts on the caliper carrier at the back of the knuckle. Off. Hang the caliper from a bungee or wire — don't let it hang on the hose. T30 set screw between the wheel-bolt holes on the rotor; rotor off with a tap of a mallet if it's stuck to the hub."}]}, {"n": 4, "title": "Three hub bolts", "blocks": [{"t": "text", "b": "Come around to the back. Three M12 12-point bolts through the knuckle into the back of the hub. 18 mm triple-square. Break each loose in place; the lowest, rearmost bolt is the tightest to reach — a longer extension and a stubby breaker bar clears the shock."}, {"t": "ill", "id": "mk7-hub-rear", "cap": "FWD rear knuckle: three bolts, no axle. The wheel-speed sensor lives on the inboard face; unplug or leave connected as fits."}]}, {"n": 5, "title": "Hub off, mating face clean", "blocks": [{"t": "text", "b": "With the three bolts out, the hub slides off the front of the knuckle. If it's rust-welded, a slide hammer with a hub adapter is the clean way; a tap of a dead-blow on alternating sides also frees it. Wire-brush the knuckle's mating face until it's shiny."}]}, {"n": 6, "title": "New hub, three new bolts, torque", "blocks": [{"t": "text", "b": "Fit the new hub, seat it flat against the clean face. Three new bolts from the back, hand-tight in a triangle, then torque in a cross pattern."}, {"t": "torque", "label": "Hub-to-knuckle bolts (M12 ×3, NEW)", "nm": 70, "note": "+90° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 90°: VWVortex Mk7 Golf R rear bearing DIY, MyGolfMk7 (M12 hub bolts)."}}]}, {"n": 7, "title": "Rotor and caliper back on", "blocks": [{"t": "text", "b": "Rotor onto the hub, T30 set screw in. Caliper bracket back on, two 14 mm triple-square bolts."}, {"t": "torque", "label": "Rotor set screw", "nm": 8, "c": {"level": "high", "n": 1, "note": "8 Nm."}}, {"t": "torque", "label": "Caliper carrier bolts (M14 ×2, NEW)", "nm": 90, "note": "+90° turn", "c": {"level": "medium", "n": 2, "note": "90 Nm + 90° for the M14 caliper carrier — cross-Mk5/Mk6 reference (single-source Mk7 confirmation pending). If you have a Bentley for the Mk7, cross-check."}}]}, {"n": 8, "title": "Parking brake back into operation", "blocks": [{"t": "text", "b": "Wheels on to hand tight. Lower the car. Lug bolts to 120 Nm. VCDS or OBDeleven again: run the counterpart routine that closes the parking-brake actuators. On VCDS this is the same Basic Settings screen with the 'Close' option; on OBDeleven the Service Position screen has an 'Exit' step."}, {"t": "note", "b": "Do not drive without running the close routine. The pistons are physically retracted; the car has no rear brakes until you tell them to come back out."}]}, {"n": 9, "title": "First drive", "blocks": [{"t": "text", "b": "Test the parking brake at a slow crawl. Then normal driving — the hum should be gone. New hum from a different corner would mean the other side is also going and it was just quieter than the loud one."}]}], "alsoReplace": [{"name": "Rear brake pads", "why": "Everything is already apart. If the pads have less than 4 mm left, do them now."}, {"name": "Rear rotor", "why": "Same reason as pads."}, {"name": "Wheel-speed sensor", "why": "$30 and right there."}], "check": {"tab": "Diagnosis", "title": "Is it the rear bearing?", "illId": "mk7-hub-rear", "illCap": "Same speed/turn test as the front, just from behind you.", "rows": [{"see": "Hum from the back that gets louder with speed", "means": "Rear bearing.", "do": "Test which side by turning — a right turn loads the left."}, {"see": "Hum that gets quieter above 55 mph", "means": "Tire noise pattern, not a bearing.", "do": "Rotate the tires first; if the noise moves, it's tires."}, {"see": "Play in the wheel on the wobble test", "means": "Bearing.", "do": "Replace both sides if there's any doubt on the other."}, {"see": "ABS light with rear wheel-speed fault", "means": "Tone ring damage or a dirty sensor.", "do": "Clean the sensor first."}], "c": {"level": "high", "n": 3, "note": "Standard bearing diagnosis; rear-specific noise patterns match VWVortex threads."}}, "aftercare": ["Test the parking brake at a crawl before the first real drive.", "Re-torque the three hub bolts and the caliper carrier at 100 miles.", "New rear noise: mating face wasn't clean, or the parking brake didn't fully re-engage."], "disagreements": [{"topic": "Caliper carrier bolt torque", "pos": "MyGolfMk7 table doesn't list the rear carrier separately; Mk5/Mk6 give 90 Nm + 90°.", "call": "90 Nm + 90°, flagged. Confirm against your service manual if you have one."}, {"topic": "Do the pads have to come off the caliper?", "pos": "Some DIYs remove the pads.", "call": "No. Hang the whole caliper by a wire; leave the pads in."}], "sources": ["VWVortex 'Mk7 Golf R Rear Wheel Bearing DIY' (William McLean, 2020) — FAG kit part numbers, 70 Nm + 90° hub bolts, VW caliper bolt PN", "MyGolfMk7 torque spec table (M12 hub bolts, rotor set screw 8 Nm)", "FCP Euro Mk5 rear wheel bearing DIY (HumbleMechanic) — diagnostic approach, single-use hub bolt", "Pelican Parts Mk5 rear wheel hub DIY (bolt-in Gen 3 layout)", "GolfMK7 wheel-bearing threads"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
